public class GridExplorer {
    public int countValidCells(int[][] grid) {
        int count = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (isValidCell(grid, r, c)) count++;
            }
        }
        return count;
    }

    private boolean isValidCell(int[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] > 0;
    }
}

