public class LinkedListReverser {
    public ListNode reverse(ListNode head) {
        ListNode prev = null;
        for (ListNode curr = head; curr != null; ) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

